import pandas as pd

CURRENCY = "$"
THOUSANDS = ","


def transform(row):
    filing_id = row["filing_id"]
    spend = _digits(row["amount_usd"])
    if spend is None:
        raise StepRefused(
            f"filing {filing_id} reports its spend as {row['amount_usd']!r}, which is "
            f"not a whole dollar figure — a filing whose spend cannot be read is not "
            f"one this workflow can weigh against a public commitment"
        )
    if not _present(row["lobbied_about"]):
        raise StepRefused(
            f"filing {filing_id} says nothing about what it asked government for, so "
            f"there is no ask to judge against its client's commitment"
        )
    return {**row, "amount_usd": spend}


def _digits(value):
    text = _present(value)
    if text is None:
        return None
    stripped = text.replace(CURRENCY, "").replace(THOUSANDS, "").strip()
    if not stripped.isdigit():
        return None
    return int(stripped)


def _present(value):
    if value is None or bool(pd.isna(value)):
        return None
    text = str(value).strip()
    return text or None

