import html as _html
import pathlib

import pandas as pd

# The page's markup, in the stage that writes it. A report stage emits a document, so
# its markup is part of what the stage IS — a reader reviewing this step reads it here
# rather than chasing a file the workflow does not carry.
DOCUMENT = """\
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Tutorial Lobbying Say-versus-Do</title>
<style>
  body { font-family: -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
         margin: 2rem auto; max-width: 1180px; padding: 0 1rem; line-height: 1.45; }
  h1 { font-size: 1.45rem; margin-bottom: .2rem; }
  p { margin: .5rem 0; }
  .sub, .note, .muted, .src { font-size: .85rem;
        color: color-mix(in srgb, currentColor 60%, transparent); }
  .note, .why { border-left: 3px solid color-mix(in srgb, currentColor 30%, transparent);
        padding: .1rem 0 .1rem .8rem; margin: 1rem 0; }
  .why { font-size: .9rem; max-width: 62ch; }
  table { border-collapse: collapse; width: 100%; font-size: .88rem; margin-top: 1.4rem; }
  th, td { text-align: left; padding: .5rem .6rem; vertical-align: top;
           border-bottom: 1px solid color-mix(in srgb, currentColor 15%, transparent); }
  th { font-size: .7rem; text-transform: uppercase; letter-spacing: .05em;
       border-bottom-width: 2px; }
  td.num { font-variant-numeric: tabular-nums; font-weight: 600; white-space: nowrap; }
  tr.flagged td:first-child { border-left: 3px solid currentColor; }
  .pill { border: 1px solid color-mix(in srgb, currentColor 30%, transparent);
          border-radius: 999px; padding: .05rem .5rem; font-size: .78rem;
          white-space: nowrap; }
  .none { color: color-mix(in srgb, currentColor 40%, transparent); font-style: italic; }
  .src { display: block; margin-top: .2rem; }
  .quote { margin: .4rem 0 0; font-size: .82rem; max-width: 44ch; }
  .reviewed { margin: .4rem 0 0; font-size: .8rem; max-width: 44ch; }
  .label { font-weight: 700; text-transform: uppercase; letter-spacing: .04em;
           font-size: .7rem; display: block; }
</style>
</head>
<body>
<h1>Tutorial Say-versus-Do Report</h1>
<p class="sub">[[filing_count]] filings; [[flagged_count]] ask government for the opposite of what their client committed to in public, each one read by a named reviewer; [[unmatched_count]] have no public commitment on record.</p>
<p class="note">Invented sample data bundled with this tutorial. No row describes a real filing, client, firm or commitment.</p>
<p class="why">Beside each filing is what the same client said in public. A model proposed a label; every
contradiction it proposed went to a person, who kept or changed it. What is printed is the person's
answer &mdash; the model's is kept beside it in the run. A marked filing prints both texts.
A reading aid, not a verdict. Every row carries a <em>Show the work</em> link back through each stage to the
filing it came from.</p>
<table>
<thead><tr>
<th>Filing</th><th>Client</th><th>Registrant</th><th>Period</th>
<th>Reported spend</th><th>What this filing asks for</th><th>What they said in public</th><th>Why follow up</th>
<th>Show the work</th>
</tr></thead>
<tbody>
[[rows]]</tbody>
</table>
</body>
</html>
"""

ROW = """\
<tr class="[[row_class]]">
<td>[[filing_id]]</td>
<td>[[client]]</td>
<td class="muted">[[registrant]]</td>
<td>[[filing_period]]</td>
<td class="num">[[amount]]</td>
<td>[[lobbied_about]]</td>
<td>[[commitment]]</td>
<td>[[followup]]</td>
<td>[[trace]]</td>
</tr>
"""

TRACE = """\
<a href="[[trace_url]]">Lineage</a>
"""

COMMITMENT = """\
[[public_commitment]]<span class="src">[[commitment_source]]</span>
"""

NO_COMMITMENT = """\
<span class="none">No public commitment on record</span>
"""

JUDGMENT = """\
<span class="pill">[[ai_judgment]]</span>
"""

REVIEW = """\
<p class="reviewed"><span class="label">[[headline]]</span>[[reviewer]], [[reviewed_at]]</p>
[[note]]
"""

REVIEW_NOTE = """\
<p class="quote">[[review_notes]]</p>
"""

CONTRADICTION = """\
<p class="quote"><span class="label">Said</span>[[said]]</p>
<p class="quote"><span class="label">Lobbied for</span>[[lobbied_for]]</p>
"""

SECTIONS = {
    "document": DOCUMENT, "row": ROW, "trace": TRACE, "commitment": COMMITMENT,
    "no_commitment": NO_COMMITMENT, "judgment": JUDGMENT, "review": REVIEW,
    "review_note": REVIEW_NOTE, "contradiction": CONTRADICTION,
}
TOKEN_OPEN = "[["


# The ordinal a trace URL needs is a position in THIS frame, so the stage it names is
# this step's own input, and the rows are rendered in the order they arrived.
TRACED_INPUT = "review_contradictions"
CONTRADICTS = "Contradicts"
NOT_REVIEWED = "skipped"
KEPT = "approve"
NO_SOURCE = "source not recorded"


def transform(df, output_dir, citation_provider):
    sections = SECTIONS
    page = _fill(
        sections["document"],
        filing_count=str(len(df)),
        flagged_count=str(sum(_contradicts(row) for _, row in df.iterrows())),
        unmatched_count=str(int(df["public_commitment"].isna().sum())),
        rows="".join(
            _render_row(sections, row, citation_provider, ordinal)
            for ordinal, (_, row) in enumerate(df.iterrows())
        ),
    )
    out_path = pathlib.Path(output_dir) / "tutorial_triage_report.html"
    out_path.write_text(page, encoding="utf-8")
    return pd.DataFrame([{"report_path": str(out_path), "filing_count": len(df)}])


def _render_row(sections, row, citation_provider, ordinal):
    return _fill(
        sections["row"],
        row_class="flagged" if _contradicts(row) else "",
        filing_id=_escaped(row["filing_id"]),
        client=_escaped(row["client"]),
        registrant=_escaped(row["registrant"]),
        filing_period=_escaped(row["filing_period"]),
        amount="$" + format(int(row["amount_usd"]), ","),
        lobbied_about=_escaped(row["lobbied_about"]),
        commitment=_render_commitment(sections, row),
        followup=_render_followup(sections, row),
        trace=_fill(
            sections["trace"],
            trace_url=_escaped(citation_provider.cite_row(TRACED_INPUT, ordinal)),
        ),
    )


def _render_commitment(sections, row):
    said = _present(row["public_commitment"])
    if said is None:
        return sections["no_commitment"]
    return _fill(
        sections["commitment"],
        public_commitment=_escaped(said),
        commitment_source=_escaped(_present(row["commitment_source"]) or NO_SOURCE),
    )


def _render_followup(sections, row):
    # A flag is not an argument: a flagged row shows both texts it was decided from.
    judgment = _fill(
        sections["judgment"], ai_judgment=_escaped(_reviewed_alignment(row))
    ) + _render_review(sections, row)
    if not _contradicts(row):
        return judgment
    said = _present(row["public_commitment"])
    if said is None:
        raise StepRefused(
            f"filing {row['filing_id']} is judged to contradict a public commitment, "
            f"yet nothing ever matched one onto it, so this report cannot say what it "
            f"contradicts"
        )
    return judgment + _fill(
        sections["contradiction"],
        said=_escaped(said),
        lobbied_for=_escaped(row["lobbied_about"]),
    )


def _render_review(sections, row):
    verdict = _present(row["review_verdict"])
    if verdict == NOT_REVIEWED:
        return ""
    reviewer = _present(row["reviewer"])
    reviewed_at = _present(row["reviewed_at"])
    if reviewer is None or reviewed_at is None:
        raise StepRefused(
            f"filing {row['filing_id']} carries a reviewed judgment with no reviewer "
            f"or time recorded against it, so this report cannot say who reviewed it or "
            f"when — an unreviewed judgment is the model's, and is not published as a "
            f"person's"
        )
    return _fill(
        sections["review"],
        headline=(
            "Confirmed" if verdict == KEPT
            else "Changed from " + _escaped(row["ai_judgment"])
        ),
        reviewer=_escaped(reviewer),
        reviewed_at=_escaped(reviewed_at),
        note=_render_note(sections, row),
    )


def _render_note(sections, row):
    note = _present(row["review_notes"])
    if note is None:
        return ""
    return _fill(sections["review_note"], review_notes=_escaped(note))


def _contradicts(row):
    return _reviewed_alignment(row) == CONTRADICTS


def _reviewed_alignment(row):
    # The published label is the reviewer's, so a row without one is not publishable.
    label = _present(row["reviewed_judgment"])
    if label is None:
        raise StepRefused(
            f"filing {row['filing_id']} reaches the report with no judgment on it at "
            f"all, neither the model's nor a reviewer's, so there is nothing to print"
        )
    return label


def _fill(template, **values):
    filled = template
    for name, value in values.items():
        filled = filled.replace(TOKEN_OPEN + name + "]]", value)
    if TOKEN_OPEN in filled:
        raise ValueError(
            "the report markup has a placeholder this step does not fill"
        )
    return filled


def _escaped(value):
    return _html.escape(str(value))


def _present(value):
    if value is None or bool(pd.isna(value)):
        return None
    return str(value)
